"""Run the original CPU-bound 24-bit resiliency optimizer and final sampling."""

import argparse
from pathlib import Path

from examples.synthesis.applications.telecom.resiliency_planning.overview import (
    main as shared_main,
)
from examples.synthesis.applications.telecom.resiliency_planning.overview import (
    plots,
    workflow,
)

QUERIES, OBJECTIVE_SHOTS, FINAL_SHOTS = 1, 1000, 40_000


def run() -> workflow.Result:
    return workflow.optimize(
        queries=QUERIES, objective_shots=OBJECTIVE_SHOTS, final_shots=FINAL_SHOTS
    )


def report(result: workflow.Result) -> None:
    shared_main.report(result)
    valid_count = sum(count for _, count in result.feasible)
    print(f"Source displayed denominator=2000, actual final draws={FINAL_SHOTS}")
    print(
        f"Source denominator-scaled valid percentage={100 * valid_count / 2000}; actual valid percentage={100 * valid_count / FINAL_SHOTS}"
    )


def main() -> None:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--figures", type=Path, default=Path("resiliency-amd-figures"))
    parser.add_argument(
        "--results", type=Path, default=Path("resiliency-amd-results.json")
    )
    args = parser.parse_args()
    result = run()
    report(result)
    plots.save(result, args.figures)
    shared_main.write(result, args.results)


if __name__ == "__main__":
    main()

"""Run original-size resiliency circuits with actual local finite sampling."""

import math
from dataclasses import dataclass
from typing import cast

import torch

import flagquantum as fq
from examples.synthesis.applications.telecom.resiliency_planning.main import (
    build_program,
)
from flagquantum.algorithms import CobylaOptimizer

from . import problem


def initial_parameters() -> tuple[float, ...]:
    return tuple(
        value
        for layer in range(20)
        for value in (
            math.pi * (2 * layer + 1) / 40,
            math.pi * (1 - (2 * layer + 1) / 40),
        )
    )


def physical_to_logical(words: torch.Tensor) -> torch.Tensor:
    out = torch.zeros_like(words)
    for bit in range(24):
        out |= ((words >> bit) & 1) << (23 - bit)
    return out


def draw(
    parameters: tuple[float, ...], shots: int, generator: torch.Generator
) -> torch.Tensor:
    program = build_program(parameters)
    state = cast(torch.Tensor, fq.run(program).statevector()).reshape(-1)
    physical = torch.multinomial(
        state.abs().square(), shots, replacement=True, generator=generator
    )
    return physical_to_logical(physical)


class _QueryBudgetError(Exception):
    """Stop before any objective query beyond the explicit local budget."""


@dataclass(frozen=True)
class Result:
    trace: tuple[tuple[tuple[float, ...], float], ...]
    parameters: tuple[float, ...]
    counts: tuple[tuple[int, int], ...]
    feasible: tuple[tuple[int, int], ...]
    objective_shots: int
    final_shots: int
    stopped: bool
    converged: bool


def optimize(
    *, queries: int = 1, objective_shots: int = 20_000, final_shots: int = 20_000
) -> Result:
    if any(
        type(value) is not int or value <= 0
        for value in (queries, objective_shots, final_shots)
    ):
        raise ValueError("Query and sample budgets must be positive integers")
    generator = torch.Generator().manual_seed(10)
    trace: list[tuple[tuple[float, ...], float]] = []

    def evaluate(params: torch.Tensor) -> torch.Tensor:
        if len(trace) >= queries:
            raise _QueryBudgetError()
        parameters = tuple(float(p) for p in params)
        cost = float(
            problem.values(draw(parameters, objective_shots, generator))[0].mean()
        )
        trace.append((parameters, cost))
        return torch.tensor(cost, dtype=torch.float64)

    stopped = converged = False
    try:
        result = CobylaOptimizer(maxiter=100, rhobeg=1.0, rhoend=1e-8).minimize(
            evaluate, torch.tensor(initial_parameters(), dtype=torch.float64)
        )
        converged = result.converged
    except _QueryBudgetError:
        stopped = True
    parameters = min(trace, key=lambda row: row[1])[0]
    words, counts = torch.unique(
        draw(parameters, final_shots, generator), return_counts=True
    )
    order = torch.argsort(counts, descending=True, stable=True)
    ordered = tuple((int(words[i]), int(counts[i])) for i in order)
    _, flow, overlap = problem.values(words)
    good = {
        int(word)
        for word, first, second in zip(words, flow, overlap, strict=True)
        if not int(first) and not int(second)
    }
    return Result(
        tuple(trace),
        parameters,
        ordered,
        tuple((word, count) for word, count in ordered if word in good),
        objective_shots,
        final_shots,
        stopped,
        converged,
    )

"""Original two-demand network resiliency objective and validity rules."""

from itertools import product

import torch

NODES = ("P1", "P2", "S1", "S2", "S3")
EDGES = (
    ("P1", "S1"),
    ("P1", "S2"),
    ("S2", "S1"),
    ("P2", "S1"),
    ("S3", "S1"),
    ("P2", "S3"),
    ("S3", "S2"),
)
DEMANDS = (("S2", "P1"), ("S2", "P2"))
LATENCY = (1, 1, 1, 1, 1, 1, 2)
WIDTH, LAYERS = 24, 20
POSITIONS = {
    "P1": (2.0, 1.0),
    "P2": (1.0, 1.0),
    "S1": (1.5, 1.0),
    "S2": (1.75, 2.0),
    "S3": (1.25, 2.0),
}


def values(words: torch.Tensor) -> tuple[torch.Tensor, torch.Tensor, torch.Tensor]:
    bits = ((words[:, None] >> torch.arange(WIDTH)) & 1).reshape(-1, 2, 12)
    latency = (bits[:, :, :7] * torch.tensor(LATENCY, dtype=torch.float64)).sum(
        dim=(1, 2)
    )
    flow = torch.zeros(words.numel(), dtype=torch.int64)
    for demand, (source, target) in enumerate(DEMANDS):
        for index, node in enumerate(NODES):
            residual = int(node in (source, target)) - 2 * bits[:, demand, 7 + index]
            for edge, endpoints in enumerate(EDGES):
                if node in endpoints:
                    residual = residual + bits[:, demand, edge]
            flow += residual.square()
        for node in (source, target):
            flow += 1 - bits[:, demand, 7 + NODES.index(node)]
    overlap = sum(
        (
            bits[:, 0, 7 + i] * bits[:, 1, 7 + i]
            for i, node in enumerate(NODES)
            if node != "S2"
        ),
        torch.zeros(words.numel(), dtype=torch.int64),
    )
    correlation = bits[:, 0, 1] * bits[:, 1, 2] + bits[:, 0, 2] * bits[:, 1, 1]
    return (
        0.025 * latency
        + 0.25 * overlap.to(torch.float64)
        + correlation.to(torch.float64)
        + 0.125 * flow.to(torch.float64),
        flow,
        overlap,
    )


def cost(word: int) -> float:
    return float(values(torch.tensor([word], dtype=torch.int64))[0][0])


def valid(word: int) -> bool:
    _, flow, overlap = values(torch.tensor([word], dtype=torch.int64))
    return not int(flow[0]) and not int(overlap[0])


def feasible_words() -> tuple[int, ...]:
    """Enumerate each original 12-bit demand and combine exact valid assignments."""
    rows = torch.arange(4096, dtype=torch.int64)
    choices: list[list[int]] = []
    for demand, (source, target) in enumerate(DEMANDS):
        bits = (rows[:, None] >> torch.arange(12)) & 1
        good = torch.ones(4096, dtype=torch.bool)
        for index, node in enumerate(NODES):
            residual = int(node in (source, target)) - 2 * bits[:, 7 + index]
            for edge, endpoints in enumerate(EDGES):
                if node in endpoints:
                    residual = residual + bits[:, edge]
            good &= residual == 0
        for node in (source, target):
            good &= bits[:, 7 + NODES.index(node)] == 1
        choices.append([int(row) for row in rows[good]])
    return tuple(
        first | second << 12
        for first, second in product(*choices)
        if valid(first | second << 12)
    )
